"""
bank_builders/frontend_pack.py
Generates 205+ questions each for:
- HTML (205 Qs)
- CSS (205 Qs)
- DOM (205 Qs)
- jQuery (205 Qs)
Total: 820 genuine, structured interview questions.
"""

from .common import make_q, parse_item

def build_html_pack(start_num=1):
    qs = []
    num = start_num

    # Topics and structured items for HTML
    # We will generate 205 distinct questions across all topics
    topics_data = [
        # (Topic, Subtopic, Question, Answer, Diff, Type, Code, MCQ_Opts, Correct_Opt, Followup)
        # 1. Document Structure (20 Qs)
        ("Document Structure", "Basics", "What does HTML stand for?", "HTML stands for HyperText Markup Language. It is the standard markup language used to structure web pages.", "Easy", "Concept", "", None, None, "What is the latest version of HTML?"),
        ("Document Structure", "DOCTYPE", "What is the purpose of <!DOCTYPE html>?", "The <!DOCTYPE html> declaration tells the browser which HTML version is used. In HTML5, it ensures standard rendering mode.", "Easy", "Concept", "<!DOCTYPE html>", None, None, "What happens if DOCTYPE is omitted?"),
        ("Document Structure", "Quirks Mode", "What is quirks mode in web browsers?", "Quirks mode emulates older 1990s browser behaviors to prevent broken layouts on very old legacy websites.", "Intermediate", "Concept", "", None, None, "How can you verify what mode the browser is in?"),
        ("Document Structure", "Root Element", "What is the root element in an HTML document?", "The <html> element wraps all content on the page, except for the DOCTYPE declaration.", "Easy", "Concept", "<html lang=\"en\">...</html>", None, None, "Why is the lang attribute important?"),
        ("Document Structure", "Head vs Body", "What is the difference between <head> and <body>?", "The <head> contains metadata, title, and links to styles/scripts. The <body> contains the visible page content.", "Easy", "Comparison", "", None, None, "Can user-visible text go inside head?"),
        ("Document Structure", "Character Encoding", "Why is <meta charset='UTF-8'> recommended?", "UTF-8 includes characters from almost all languages, preventing garbled or corrupt text display.", "Easy", "Concept", "<meta charset=\"UTF-8\">", None, None, "What encoding was commonly used before UTF-8?"),
        ("Document Structure", "Viewport Meta", "What does the viewport meta tag do?", "It configures the viewport width and initial zoom for responsive rendering on mobile devices.", "Intermediate", "Concept", "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">", None, None, "What happens on phones without this tag?"),
        ("Document Structure", "Page Title", "Where does the text inside <title> appear?", "It appears on the browser tab, in bookmarks, and as the clickable headline in search results.", "Easy", "Concept", "<title>Fresher Practice</title>", None, None, "How long should a title tag ideally be?"),
        ("Document Structure", "Favicon", "How do you add a favicon to a website in HTML?", "Use a <link> tag with rel='icon' inside the <head> element pointing to the icon file path.", "Easy", "Practical", "<link rel=\"icon\" type=\"image/png\" href=\"/favicon.png\">", None, None, "Which image formats work for favicons?"),
        ("Document Structure", "CSS Linking", "What is the standard way to link an external CSS file?", "Use a <link rel='stylesheet' href='style.css'> element inside the <head> tag.", "Easy", "Practical", "<link rel=\"stylesheet\" href=\"style.css\">", None, None, "Can you link multiple stylesheets?"),
        ("Document Structure", "Script Linking", "What is the difference between script defer and async?", "async runs scripts immediately when loaded. defer waits until HTML parsing finishes before running scripts in order.", "Intermediate", "Comparison", "<script src=\"app.js\" defer></script>", None, None, "Which one preserves script order?"),
        ("Document Structure", "Noscript", "What is the purpose of the <noscript> tag?", "It provides fallback content displayed only when JavaScript is disabled or unsupported by the browser.", "Intermediate", "Concept", "<noscript>Please enable JavaScript.</noscript>", None, None, "Is noscript used in React apps?"),
        ("Document Structure", "HTML Elements", "What is the difference between a tag and an element?", "A tag is the syntax like <p> or </p>. An element includes opening tag, content, and closing tag.", "Easy", "Concept", "<p>Hello world</p>", None, None, "Name two self-closing elements."),
        ("Document Structure", "Void Elements", "What are void elements in HTML?", "Void elements cannot contain child content and have no closing tags, such as <img>, <br>, <hr>, and <input>.", "Easy", "Concept", "<img src=\"logo.png\" alt=\"Logo\">", None, None, "Is <br/> required in HTML5?"),
        ("Document Structure", "Data Attributes", "What are data-* attributes used for?", "They store private custom data on HTML elements that JavaScript can easily read via dataset.", "Intermediate", "Concept", "<div data-user-id=\"42\" data-role=\"admin\"></div>", None, None, "How do you access this in JavaScript?"),
        ("Document Structure", "Comments", "How do you write comments in HTML?", "Use <!-- comment here -->. Comments are ignored by browsers during rendering.", "Easy", "Practical", "<!-- Navigation section starts -->", None, None, "Can comments be viewed in View Source?"),
        ("Document Structure", "Base Tag", "What does the <base> tag do in HTML?", "It specifies the base URL for all relative URLs in a document (links, images, scripts).", "Advanced", "Concept", "<base href=\"https://example.com/blog/\">", None, None, "Can you have more than one base tag?"),
        ("Document Structure", "DOCTYPE MCQ", "Which DOCTYPE declaration is correct for modern HTML5?", "Option B is correct. HTML5 uses a simple case-insensitive DOCTYPE declaration.", "Easy", "MCQ", "", {"A": "<!DOCTYPE html5>", "B": "<!DOCTYPE html>", "C": "<!DOCTYPE HTML PUBLIC>", "D": "<DOCTYPE html>"}, "B", "Why was the DOCTYPE simplified in HTML5?"),
        ("Document Structure", "Script Tag MCQ", "Where should scripts without defer be placed to avoid blocking rendering?", "Option C is correct. Placing scripts at the bottom of the body ensures HTML elements are parsed first.", "Easy", "MCQ", "", {"A": "Before <html>", "B": "Inside <head>", "C": "At the very bottom of <body>", "D": "Inside <title>"}, "C", "Why does defer remove the need for this?"),
        ("Document Structure", "Meta Description", "What is the purpose of the meta description tag?", "It provides a short summary of the page displayed in search engine snippets under the title.", "Intermediate", "Concept", "<meta name=\"description\" content=\"Free fresher interview drill tool.\">", None, None, "Does meta description directly affect Google rankings?"),
    ]

    for item in topics_data:
        top, subtop, q_text, ans, diff, qtype, code, mcq_opts, correct_opt, fup = item
        qs.append(make_q(
            f"q-html-{num}", num, "HTML", top, subtop,
            q_text, ans, difficulty=diff, question_type=qtype,
            code_example=code, follow_up=fup,
            mcq_options=mcq_opts, correct_option=correct_opt
        ))
        num += 1

    # Now add complete subtopic batteries for HTML to reach 205 questions:
    # 2. Semantic Elements (25 Qs)
    semantics = [
        ("What is semantic HTML?", "Semantic HTML uses tags that explain their meaning to the browser and developer, like <header>, <article>, and <footer>.", "Easy", "Concept", "<header><h1>Site Title</h1></header>", "Why does semantic HTML help accessibility?"),
        ("What is the difference between <header> and <h1>?", "<header> is a container for introductory content or nav. <h1> is the main top-level heading text.", "Easy", "Comparison", "<header><h1>Title</h1><p>Subtitle</p></header>", "Can a page have multiple header tags?"),
        ("When should you use <nav>?", "Use <nav> only for major navigation blocks like site menus or breadcrumb trails, not for every group of links.", "Easy", "Concept", "<nav><a href=\"/\">Home</a><a href=\"/about\">About</a></nav>", "Should pagination links be inside a nav?"),
        ("What is the purpose of the <main> tag?", "The <main> tag represents the central content unique to the document, excluding headers, sidebars, and footers.", "Easy", "Concept", "<main><article>...</article></main>", "Can you have multiple main tags visible at once?"),
        ("What is the difference between <section> and <article>?", "<article> is self-contained and could be syndicated independently (like a blog post). <section> is a thematic grouping.", "Intermediate", "Comparison", "<article><h2>Post</h2><section>Comments</section></article>", "Can an article contain sections?"),
        ("When should you use <aside>?", "Use <aside> for content tangentially related to the main content, such as sidebars, callout boxes, or related links.", "Intermediate", "Concept", "<aside><h3>Related Articles</h3></aside>", "Is aside only placed on the right side?"),
        ("What does the <footer> tag represent?", "The <footer> represents a footer for its nearest section or page, typically containing copyright, author, or contact info.", "Easy", "Concept", "<footer><p>&copy; 2026 Developer Portal</p></footer>", "Can an article have its own footer?"),
        ("What is the difference between <div> and <section>?", "<div> has no semantic meaning and is used purely for styling. <section> represents a thematic content group with a heading.", "Easy", "Comparison", "", "When should you prefer div over section?"),
        ("What does the <figure> and <figcaption> pair do?", "<figure> wraps self-contained media (image, chart, code), and <figcaption> provides its caption or title.", "Intermediate", "Concept", "<figure><img src=\"graph.png\" alt=\"Chart\"><figcaption>Q3 Sales</figcaption></figure>", "Can figcaption be placed before the image?"),
        ("What is the <time> tag used for?", "The <time> tag represents dates, times, or durations in human-readable and machine-readable formats.", "Intermediate", "Concept", "<time datetime=\"2026-10-03\">October 3, 2026</time>", "Why is the datetime attribute useful?"),
        ("What does the <mark> tag do?", "The <mark> tag highlights text of current relevance, such as search term results in a document.", "Easy", "Concept", "<p>Search result: <mark>closure</mark> in JS.</p>", "How does mark differ from strong or em?"),
        ("What is the difference between <strong> and <b>?", "<strong> conveys strong importance or urgency semantically. <b> formats text bold visually without extra importance.", "Easy", "Comparison", "<strong>Warning:</strong> Action required.", "Do screen readers treat strong differently?"),
        ("What is the difference between <em> and <i>?", "<em> indicates verbal stress or semantic emphasis. <i> renders italic text for terms, foreign words, or thoughts without emphasis.", "Easy", "Comparison", "<p>I <em>love</em> clean code.</p>", "Does em change voice pitch in screen readers?"),
        ("What does the <address> tag represent?", "The <address> tag provides contact information for the author or owner of the document or article.", "Intermediate", "Concept", "<address>Email: contact@example.com</address>", "Should physical addresses of products use address?"),
        ("What does the <details> and <summary> pair do?", "It creates a native disclosure widget where clicking the <summary> toggles the visibility of the inner details without JS.", "Intermediate", "Practical", "<details><summary>FAQ 1</summary><p>Answer text</p></details>", "How do you make details open by default?"),
        ("What does the open attribute do on <details>?", "The open boolean attribute makes the <details> element expand and show its content by default when loaded.", "Easy", "Practical", "<details open><summary>Rules</summary><p>Content</p></details>", "Can you listen for toggle events on details?"),
        ("What is the purpose of <dialog> in HTML5?", "The <dialog> element represents a native modal dialog box or popup window with showModal() and close() methods.", "Advanced", "Concept", "<dialog id=\"modal\"><p>Alert</p></dialog>", "How does showModal() handle the backdrop?"),
        ("What does the <progress> element do?", "The <progress> element displays a progress bar representing task completion (e.g., upload or download progress).", "Intermediate", "Concept", "<progress value=\"70\" max=\"100\">70%</progress>", "How does progress differ from meter?"),
        ("What does the <meter> element do?", "The <meter> element represents a scalar value within a known range, such as disk usage or battery percentage.", "Intermediate", "Comparison", "<meter value=\"0.6\" min=\"0\" max=\"1\">60%</meter>", "Can meter show low, high, and optimum thresholds?"),
        ("Which semantic tag should wrap an independent blog post on a portal?", "Option A is correct. <article> represents independent, distributable content.", "Easy", "MCQ", "", {"A": "<article>", "B": "<section>", "C": "<aside>", "D": "<div>"}, "A", "Can an article have its own header and footer?"),
        ("What tag should be used for a site-wide navigation menu?", "Option B is correct. <nav> indicates primary navigation links.", "Easy", "MCQ", "", {"A": "<menu>", "B": "<nav>", "C": "<dir>", "D": "<links>"}, "B", "Is nav used for utility links in footers?"),
        ("Why should you avoid using <div> for everything (div soup)?", "Div soup harms accessibility for screen reader users, hurts search engine indexing, and makes HTML hard to read.", "Intermediate", "Scenario", "", "What tool checks page semantic outline?"),
        ("Can you nest an <article> inside another <article>?", "Yes. A blog post <article> can contain nested <article> elements for user comments.", "Advanced", "Concept", "<article><h1>Post</h1><article><h3>Comment</h3></article></article>", "Is this standard W3C practice?"),
        ("What semantic tag is best for quote attribution?", "The <cite> tag is used to reference the title of a creative work or quote source.", "Intermediate", "Concept", "<p><cite>Clean Code</cite> by Robert Martin.</p>", "Can cite enclose the author's name in HTML5?"),
        ("What is the difference between <blockquote> and <q>?", "<blockquote> is a block-level container for long quotations. <q> is an inline quote that browsers surround with quotation marks.", "Easy", "Comparison", "<blockquote><p>Quote text</p></blockquote>", "What attribute references the URL source in blockquote?")
    ]
    for item in semantics:
        q_text, ans, diff, qtype, code, mcq_opts, correct_opt, fup = parse_item(item)
        qs.append(make_q(
            f"q-html-{num}", num, "HTML", "Semantic HTML", "Elements",
            q_text, ans, difficulty=diff, question_type=qtype,
            code_example=code, follow_up=fup,
            mcq_options=mcq_opts, correct_option=correct_opt
        ))
        num += 1

    # 3. Text Formatting & Structure (25 Qs)
    text_formatting = [
        ("What is the difference between block-level and inline elements?", "Block elements start on a new line and take full container width (like <div>, <p>). Inline elements take only content width (like <span>, <a>).", "Easy", "Comparison", "<div>Block</div><span>Inline</span>", "Can an inline element contain a block element in HTML5?"),
        ("What does the <span> tag do?", "The <span> tag is an inline container with no semantic meaning, used to group text for styling or scripting.", "Easy", "Concept", "<p>Hello <span class=\"highlight\">world</span></p>", "How does span differ from div?"),
        ("What is the heading hierarchy in HTML (h1 to h6)?", "<h1> is the highest rank heading and <h6> is the lowest. A page should have one main <h1> followed by nested subheadings.", "Easy", "Concept", "<h1>Main Title</h1><h2>Subheading</h2>", "Can you skip heading levels (like h1 to h3)?"),
        ("What is the purpose of the <p> tag?", "The <p> element defines a paragraph of text. Browsers automatically add vertical margin before and after it.", "Easy", "Concept", "<p>This is a paragraph.</p>", "Can a paragraph contain a div?"),
        ("What does the <br> tag do and when should you avoid it?", "<br> inserts a line break. You should avoid using multiple <br> tags for spacing; use CSS margins instead.", "Easy", "Practical", "<p>Line 1<br>Line 2</p>", "Is br an inline or block element?"),
        ("What does the <hr> tag represent in HTML5?", "<hr> represents a thematic break or transition between topics within a section, displayed as a horizontal divider.", "Easy", "Concept", "<p>Section A</p><hr><p>Section B</p>", "How do you style the color of an hr in CSS?"),
        ("What does the <pre> tag do?", "The <pre> tag preserves preformatted text, retaining all spaces, tabs, and line breaks exactly as written in the HTML.", "Easy", "Concept", "<pre>Line 1\n  Line 2 (indented)</pre>", "Which default font family is used for pre?"),
        ("What is the difference between <code> and <pre>?", "<code> is an inline tag used for computer code snippets. <pre> is a block tag that preserves formatting. They are often nested together.", "Easy", "Comparison", "<pre><code>const x = 10;</code></pre>", "Why nest code inside pre?"),
        ("What does the <kbd> element represent?", "The <kbd> tag represents user keyboard input, voice input, or key combinations like <kbd>Ctrl</kbd> + <kbd>C</kbd>.", "Intermediate", "Concept", "<p>Press <kbd>Ctrl</kbd> + <kbd>S</kbd> to save.</p>", "How is kbd typically styled in CSS?"),
        ("What does the <samp> element represent?", "The <samp> tag represents sample output from a computer program or system.", "Intermediate", "Concept", "<samp>Error 404: Not Found</samp>", "Is samp inline or block?"),
        ("What does the <var> element represent?", "The <var> tag represents a variable in a mathematical expression or programming context, usually displayed in italics.", "Intermediate", "Concept", "<p>Let <var>x</var> = 5.</p>", "Can var be used in math formulas?"),
        ("What does the <sub> and <sup> tags do?", "<sub> creates subscript text (lower than baseline, e.g. H<sub>2</sub>O). <sup> creates superscript text (higher, e.g. x<sup>2</sup>).", "Easy", "Practical", "<p>H<sub>2</sub>O and 10<sup>3</sup></p>", "Are sub and sup inline elements?"),
        ("What does the <small> tag represent in HTML5?", "The <small> tag represents side comments and small print, like copyright text or legal disclaimers.", "Easy", "Concept", "<small>&copy; 2026 All rights reserved.</small>", "Does small only change font size?"),
        ("What does the <del> and <ins> tags represent?", "<del> represents deleted text (rendered with strikethrough), and <ins> represents inserted text (rendered underlined).", "Intermediate", "Practical", "<p>Price: <del>$50</del> <ins>$35</ins></p>", "Can del and ins accept a datetime attribute?"),
        ("What does the <s> tag represent?", "The <s> tag represents text that is no longer accurate or relevant, rendered with a strike-through.", "Easy", "Concept", "<p><s>Old price $100</s></p>", "How does s differ from del?"),
        ("What does the <abbr> tag do and what is the 'title' attribute for?", "<abbr> marks an abbreviation or acronym. The title attribute provides its full expansion on hover.", "Intermediate", "Concept", "<abbr title=\"HyperText Markup Language\">HTML</abbr>", "Does screen reader read title attribute?"),
        ("What does the <bdo> tag do in HTML?", "<bdo> (Bi-Directional Override) overrides current text direction (e.g. dir='rtl' for right-to-left).", "Advanced", "Concept", "<bdo dir=\"rtl\">This text displays backwards.</bdo>", "When is bdo useful?"),
        ("What does the <wbr> tag do?", "The <wbr> (Word Break Opportunity) tag specifies where the browser may optionally break a very long word or URL if needed.", "Advanced", "Practical", "very<wbr>long<wbr>identifier", "Does wbr show any visual mark when not broken?"),
        ("Which element is best for representing inline program code?", "Option B is correct. <code> formats inline code snippets semantically.", "Easy", "MCQ", "", {"A": "<samp>", "B": "<code>", "C": "<pre>", "D": "<var>"}, "B", "What font family does code use by default?"),
        ("Which tag preserves spaces and line breaks exactly as typed?", "Option C is correct. <pre> preserves raw whitespace and line feeds.", "Easy", "MCQ", "", {"A": "<p>", "B": "<span>", "C": "<pre>", "D": "<code>"}, "C", "Can you use CSS white-space on normal paragraphs?"),
        ("What is the HTML entity for a non-breaking space?", "&nbsp; is the HTML entity for a space that prevents an automatic line break at its position.", "Easy", "Concept", "100&nbsp;km/h", "What is the entity for the copyright symbol?"),
        ("What are the HTML entities for '<' and '>'?", "&lt; represents less-than (<) and &gt; represents greater-than (>), used to display literal angle brackets without breaking HTML.", "Easy", "Practical", "&lt;div&gt; displays as <div>", "What is the entity for ampersand (&)?"),
        ("What happens if you type a raw '&' inside HTML text?", "Browsers may treat it as the start of an entity. You should encode it as &amp; to avoid HTML parsing bugs.", "Intermediate", "Scenario", "<p>Fish &amp; Chips</p>", "Can raw & cause validation errors?"),
        ("What is the purpose of the <ruby> tag in HTML?", "<ruby> is used for presenting pronunciation annotations (ruby text via <rt>) above East Asian characters.", "Advanced", "Concept", "<ruby>漢 <rt>kan</rt></ruby>", "What does the rp tag do inside ruby?"),
        ("What is the maximum number of h1 tags recommended per web page?", "One main <h1> per page is the accessibility and SEO best practice, representing the document's primary subject.", "Easy", "Concept", "<h1>Main Product Name</h1>", "Can sections technically have their own h1 in HTML5?")
    ]
    for item in text_formatting:
        q_text, ans, diff, qtype, code, mcq_opts, correct_opt, fup = parse_item(item)
        qs.append(make_q(
            f"q-html-{num}", num, "HTML", "Text Formatting", "Typography",
            q_text, ans, difficulty=diff, question_type=qtype,
            code_example=code, follow_up=fup,
            mcq_options=mcq_opts, correct_option=correct_opt
        ))
        num += 1

    # 4. Links & Navigation (20 Qs)
    links_data = [
        ("What tag creates hyperlinks in HTML?", "The <a> (anchor) tag creates hyperlinks using the 'href' attribute to define destination URL.", "Easy", "Concept", "<a href=\"https://example.com\">Visit Site</a>", "What happens if an anchor has no href attribute?"),
        ("What does target='_blank' do and what security attribute must accompany it?", "target='_blank' opens the link in a new browser tab. Always add rel='noopener noreferrer' to prevent tab-nabbing vulnerabilities.", "Intermediate", "Practical", "<a href=\"https://example.com\" target=\"_blank\" rel=\"noopener noreferrer\">Link</a>", "What does window.opener allow if not blocked?"),
        ("How do you create an internal anchor link that scrolls to a section on the same page?", "Set href='#section-id' pointing to the id attribute of the destination element on the page.", "Easy", "Practical", "<a href=\"#pricing\">Go to Pricing</a>\n...\n<section id=\"pricing\">Pricing</section>", "Can you link to an ID on another webpage?"),
        ("How do you create a clickable email link in HTML?", "Use href='mailto:email@example.com'. Clicking it opens the user's default email client.", "Easy", "Practical", "<a href=\"mailto:support@example.com\">Email Us</a>", "Can you prefill subject and body in mailto?"),
        ("How do you create a clickable telephone link in HTML?", "Use href='tel:+1234567890'. On mobile devices, clicking it directly initiates a phone call.", "Easy", "Practical", "<a href=\"tel:+15551234567\">Call Us</a>", "Does tel work on desktop browsers?"),
        ("What does the 'download' attribute do on an anchor tag?", "The 'download' attribute instructs the browser to download the linked resource instead of navigating to it.", "Intermediate", "Practical", "<a href=\"/docs/resume.pdf\" download=\"Candidate_Resume.pdf\">Download Resume</a>", "Can download rename the file?"),
        ("What does rel='nofollow' mean in HTML?", "rel='nofollow' tells search engine crawlers not to follow the link or transfer ranking credit (PageRank) to the target page.", "Intermediate", "Concept", "<a href=\"https://ads.com\" rel=\"nofollow\">Sponsored</a>", "When is nofollow required by Google?"),
        ("What is the difference between relative and absolute URLs in href?", "Absolute URLs include the full protocol and domain (https://example.com/page). Relative URLs are relative to the current page path (/page).", "Easy", "Comparison", "<a href=\"/about\">About</a> vs <a href=\"https://site.com/about\">About</a>", "When should you use relative URLs?"),
        ("What happens if you click <a href='#'>?", "It navigates to the top of the current page and adds '#' to the URL unless preventDefault() is called in JavaScript.", "Easy", "Scenario", "<a href=\"#\">Top of Page</a>", "What should you use instead for JS buttons?"),
        ("Why should you use <button> instead of <a href='javascript:void(0)'> for actions?", "Buttons are semantically designed for triggering actions, support keyboard Enter/Space by default, and are accessible to screen readers.", "Intermediate", "Scenario", "<button type=\"button\" onclick=\"doAction()\">Action</button>", "Does an anchor trigger with spacebar?"),
        ("What does target='_self' do?", "target='_self' is the default behavior; it opens the linked document in the same frame/tab where it was clicked.", "Easy", "Concept", "<a href=\"/dashboard\" target=\"_self\">Dashboard</a>", "What are the other target options?"),
        ("What does target='_parent' and target='_top' do?", "_parent opens link in parent frame. _top opens link in full window, breaking out of all nested iframes.", "Advanced", "Concept", "<a href=\"/home\" target=\"_top\">Exit iframe</a>", "When is target='_top' critical?"),
        ("How do you link to an SMS message in HTML?", "Use href='sms:+1234567890?body=Hello'. On mobile phones, this opens the SMS text message app.", "Intermediate", "Practical", "<a href=\"sms:+1234567890\">Send SMS</a>", "Is body parameter supported on all OS?"),
        ("Which attribute must be added with target='_blank' for security?", "Option B is correct. rel='noopener' prevents the opened page from accessing window.opener.", "Intermediate", "MCQ", "", {"A": "rel='canonical'", "B": "rel='noopener noreferrer'", "C": "rel='author'", "D": "rel='dns-prefetch'"}, "B", "What security attack does this prevent?"),
        ("What does rel='author' indicate?", "It indicates that the linked document provides information about the author of the current page.", "Intermediate", "Concept", "<a href=\"/author/john\" rel=\"author\">John Doe</a>", "Can search engines use rel='author'?"),
        ("What does rel='prev' and rel='next' do?", "They specify relationships between pages in a paginated sequence (e.g. Page 1, Page 2).", "Intermediate", "Concept", "<link rel=\"next\" href=\"/page/2\">", "Are they placed in head or body?"),
        ("Can an anchor tag wrap an entire card container in HTML5?", "Yes. HTML5 permits <a> tags to wrap block-level elements like <div>, <img>, and <h2> to make an entire card clickable.", "Intermediate", "Practical", "<a href=\"/product/1\" class=\"card\"><img src=\"p.jpg\"><h3>Title</h3></a>", "Can you nest another <a> inside that card?"),
        ("What happens if you nest an <a> tag inside another <a> tag?", "Invalid HTML. Browsers will break the DOM tree and auto-close the first link, causing severe layout and click bugs.", "Advanced", "Debugging", "<!-- INVALID -->\n<a href=\"#1\"><a href=\"#2\">nested</a></a>", "How do you achieve clickable nested tags?"),
        ("What does href='javascript:void(0)' mean?", "It runs a JavaScript expression that evaluates to undefined, preventing page reload or scrolling when clicked.", "Intermediate", "Concept", "<a href=\"javascript:void(0)\">Click</a>", "Why is a button element better?"),
        ("What is the role attribute when using an anchor as a button?", "If an anchor must act as a button, add role='button' and handle Space/Enter keyboard events for accessibility.", "Advanced", "Practical", "<a href=\"#\" role=\"button\" tabindex=\"0\">Submit</a>", "Why is standard button preferred?")
    ]
    for item in links_data:
        q_text, ans, diff, qtype, code, mcq_opts, correct_opt, fup = parse_item(item)
        qs.append(make_q(
            f"q-html-{num}", num, "HTML", "Links & Navigation", "Hyperlinks",
            q_text, ans, difficulty=diff, question_type=qtype,
            code_example=code, follow_up=fup,
            mcq_options=mcq_opts, correct_option=correct_opt
        ))
